<?php require __DIR__.'/../config.php';require __DIR__.'/../functions.php';requireAdmin();$pdo=db();$id=(int)($_GET['id']??0);$car=null;if($id){$s=$pdo->prepare('SELECT * FROM cars WHERE id=?');$s->execute([$id]);$car=$s->fetch();if(!$car)redirect('cars.php');}$error='';
