if($new){$pdo->prepare('DELETE FROM car_images WHERE car_id=?')->execute([$id]);$ins=$pdo->prepare('INSERT INTO car_images(car_id,image_url,angle_no) VALUES(?,?,?)');foreach($new as $i=>$u)$ins->execute([$id,$u,$i]);if(!$url && $new[0])$pdo->prepare('UPDATE cars SET image_url=? WHERE id=?')->execute([$new[0],$id]);}
flash('success','Vehicle saved successfully.');redirect('cars.php');}catch(Throwable $e){$error=$e->getMessage();}}
$gallery=[];if($id){$q=$pdo->prepare('SELECT * FROM car_images WHERE car_id=? ORDER BY angle_no');$q->execute([$id]);$gallery=$q->fetchAll();}adminTop($id?'Edit Vehicle':'Add Vehicle','cars');if($error):?><div class="flash error"><?=e($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data" class="panel form-grid wide-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="form-two"><label>Vehicle name *<input name="name" value="<?=e($car['name']??'')?>" required></label><label>Type *<input name="type" value="<?=e($car['type']??'')?>" required></label></div><div class="form-two"><label>Budget<select name="budget"><option value="low" <?=($car['budget']??'')==='low'?'selected':''?>>Low</option><option value="medium" <?=($car['budget']??'medium')==='medium'?'selected':''?>>Medium</option><option value="high" <?=($car['budget']??'')==='high'?'selected':''?>>High</option></select></label><label>Seats *<input type="number" name="seats" min="1" value="<?=e($car['seats']??5)?>" required></label></div><div class="form-two"><label>Day price ₹<input type="number" step="0.01" name="day_price" value="<?=e($car['day_price']??0)?>" required></label><label>KM price ₹<input type="number" step="0.01" name="km_price" value="<?=e($car['km_price']??0)?>" required></label></div><div class="form-two"><label>Transmission<input name="transmission" value="<?=e($car['transmission']??'Manual')?>"></label><label>Fuel<input name="fuel" value="<?=e($car['fuel']??'Diesel')?>"></label></div><div class="form-two"><label>AC<input name="ac" value="<?=e($car['ac']??'Automatic AC')?>"></label><label>Luggage<input name="luggage" value="<?=e($car['luggage']??'Large luggage space')?>"></label></div><div class="form-two"><label>Model year<input name="model_year" value="<?=e($car['model_year']??date('Y'))?>"></label><label>Main image upload<input type="file" name="main_image" accept="image/jpeg,image/png,image/webp"></label></div><label>Main image URL (optional)<input 